      (runtime->page == VS_PAGE_HISTORY || runtime->page == VS_PAGE_HISTORY_BLANK ||
       (runtime->page == VS_PAGE_NET_SWITCHING && !runtime->network_busy)))
    {
      runtime->page = VS_PAGE_NET_SWITCHING;
      runtime->progress = event->progress;
      return;
