 ****************************************************************************/

int main(int argc, char *argv[])
{
  struct sigaction act;
  const struct sc_verdict_s *verdict = &g_mock_cases[0];
  bool real_capture = true;
  int count = 1;
  int i;
  int ret = OK;

  for (i = 1; i < argc; i++)
    {
      if (strcmp(argv[i], "mock") == 0)
        {
